{
  "metric": "cogs",
  "periodA": "2026-08",
  "periodB": "2026-09",
  "answerable": true,
  "missData": null,
  "hypotheses": [
    {
      "id": "h1",
      "driverType": "supplier_price",
      "text": "Vendor invoiced above contracted unit price for specific SKUs in September, creating excess COGS.",
      "checks": "SELECT pl.vendor_id, pl.period, SUM((pl.amount_cad) - (pl.qty * pl.contract_unit_price * pl.fx_rate)) AS excess_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.vendor v ON pl.vendor_id = v.vendor_id WHERE pl.period IN ('2026-08','2026-09') GROUP BY pl.vendor_id, pl.period HAVING excess_cad > 0"
    },
    {
      "id": "h2",
      "driverType": "volume",
      "text": "Total quantity purchased changed between August and September.",
      "checks": "SELECT period, SUM(qty) AS total_qty FROM lightning.metastore.finmozg.finance_usl.purchase_line WHERE period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h3",
      "driverType": "mix",
      "text": "The mix of purchased SKUs shifted toward higher‑cost items in September.",
      "checks": "SELECT pl.period, SUM(pl.qty * p.wholesale_price_cad) / SUM(pl.qty) AS weighted_avg_wholesale_price_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.product p ON pl.sku = p.sku WHERE pl.period IN ('2026-08','2026-09') GROUP BY pl.period"
    },
    {
      "id": "h4",
      "driverType": "fx",
      "text": "Changes in USD/CAD exchange rate increased the CAD cost of USD‑denominated vendor invoices in September.",
      "checks": "SELECT pl.period, AVG(pl.fx_rate) AS avg_fx_rate FROM lightning.metastore.finmozg.finance_usl.purchase_line pl WHERE pl.currency = 'USD' AND pl.period IN ('2026-08','2026-09') GROUP BY pl.period"
    },
    {
      "id": "h5",
      "driverType": "booking_error",
      "text": "Duplicate AP invoices were booked for the same vendor invoice number, inflating COGS.",
      "checks": "SELECT vb.vendor_invoice_no, COUNT(*) AS invoice_cnt FROM lightning.metastore.finmozg.finance_usl.vendor_bill vb WHERE vb.period IN ('2026-08','2026-09') GROUP BY vb.vendor_invoice_no HAVING COUNT(*) > 1"
    },
    {
      "id": "h6",
      "driverType": "opex",
      "text": "Marketing expense (6100) increased significantly in September, contributing to overall P&L pressure.",
      "checks": "SELECT period, amount_cad FROM lightning.metastore.finmozg.finance_usl.gl_balance WHERE account_code = '6100' AND period IN ('2026-08','2026-09')"
    },
    {
      "id": "h7",
      "driverType": "supplier_price",
      "text": "Vendor VEND‑SNC paid above contract prices for SKUs NUT‑ALM, NUT‑CAS, NUT‑PEC in September 2026 (confirmed from prior close).",
      "checks": "SELECT pl.vendor_id, pl.period, SUM((pl.amount_cad) - (pl.qty * pl.contract_unit_price * pl.fx_rate)) AS excess_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.vendor v ON pl.vendor_id = v.vendor_id WHERE v.vendor_name = 'VEND-SNC' AND pl.period IN ('2026-08','2026-09') GROUP BY pl.vendor_id, pl.period"
    }
  ]
}
